/* Archival facts are separate from the deterministic demonstration event stream. */
'use strict';
const rosterSource='https://vpf.vn/tai-lieu-vleague/vleague-thong-bao/danh-sach-dang-ky-thi-dau-clb-ha-noi-vs-clb-cong-an-ha-noi-vong-15-vdqg-lpbank-2025-26/';
const archiveTeams=[
  {name:'Hà Nội',coach:'Harry Kewell',color:'#7658bf',record:[6,3,5],starters:[[1,'Quan Văn Chuẩn','TM',10,0],[2,'Đỗ Duy Mạnh','HV',14,0],[7,'Phạm Xuân Mạnh','HV',14,2],[10,'Nguyễn Văn Quyết','TĐ',13,1],[11,'Đỗ Hoàng Hên','TV',8,4],[14,'Nguyễn Hai Long','TV',13,1],[16,'Nguyễn Thành Chung','HV',12,0],[22,'Nguyễn Công Nhật','HV',10,0],[35,'Ferreira Da Silva Adriel Tadeu','HV',8,0],[77,'David Fisher','TĐ',3,1],[88,'Đỗ Hùng Dũng','TV',10,1]],subs:[[5,'Nguyễn Văn Hoàng','TM'],[9,'Phạm Tuấn Hải','TĐ'],[21,'Vũ Đình Hai','TV'],[23,'Nguyễn Văn Tùng','TĐ'],[25,'Lê Xuân Tú','TV'],[67,'Trần Văn Thắng','HV'],[68,'Vũ Tiến Long','HV'],[80,'Luiz Fernando Nascimento','TĐ'],[92,'Nguyễn Hà Anh Tuấn','TĐ']]},
  {name:'Công an Hà Nội',coach:'Polking Alexandre',color:'#e0784e',record:[11,2,0],starters:[[1,'Nguyễn Filip','TM',11,0],[5,'Đoàn Văn Hậu','HV',3,0],[6,'Mauk Stefan Ingo','TV',1,0],[7,'Cao Pendant Quang Vinh','HV',12,1],[9,'Nguyễn Đình Bắc','TĐ',12,0],[10,'Leonardo Artur De Melo','TĐ',10,6],[11,'Lê Phạm Thành Long','TV',12,0],[19,'Nguyễn Quang Hải','TV',13,5],[21,'Trần Đình Trọng','HV',13,0],[68,'Bùi Hoàng Việt Anh','HV',5,0],[88,'Lê Văn Đô','TV',11,2]],subs:[[8,'Rosa Nascimento Vitor Hugo','TV'],[15,'Bùi Xuân Thịnh','TV'],[20,'Phan Văn Đức','TĐ'],[22,'Phạm Minh Phúc','HV'],[25,'Trần Đình Minh Hoàng','TM'],[26,'Hà Văn Phương','HV'],[30,'Alves Rogerio Dos Santos','TĐ'],[38,'Adou Leygley Minh','HV'],[98,'Giáp Tuấn Dương','HV']]}
];
const lab={team:0,player:'all',period:'all',minute:90,view:'heat',shot:null,lambda:[1.5,1.2],transferType:'all',transferClub:'all',query:'',statSort:'touches'};
const sum=(rows,key)=>rows.reduce((n,r)=>n+r[key],0);
const sourceLink=(url,text='Nguồn chính thức ↗')=>`<a class="text-link" href="${url}" ${url.startsWith("#")?"":"target=\"_blank\" rel=\"noopener\""}>${text}</a>`;
function demoEvents(){
  let seed=27319;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
  const rows=[];
  for(let side=0;side<2;side++)for(let i=0;i<440;i++){
    const player=Math.floor(random()*11),p=archiveTeams[side].starters[player],base=p[2]==='TM'?10:p[2]==='HV'?35:p[2]==='TV'?57:76;
    rows.push({id:`t${side}-${i}`,side,player,minute:1+Math.floor(random()*90),x:Math.max(2,Math.min(98,base+(random()+random()-1)*48)),y:3+random()*94,type:'touch'});
  }
  for(let side=0;side<2;side++)for(let i=0;i<(side===0?14:11);i++){
    const attackers=archiveTeams[side].starters.map((p,i)=>({p,i})).filter(x=>x.p[2]!=='TM');
    rows.push({id:`s${side}-${i}`,side,player:attackers[Math.floor(random()*attackers.length)].i,minute:3+Math.floor(random()*87),x:70+random()*27,y:20+random()*60,type:'shot',xg:Math.round((.03+random()*.25)*100)/100,onTarget:i<(side===0?2:1)||i%3===0,goal:i<(side===0?2:1)});
  }
  return rows.sort((a,b)=>a.minute-b.minute);
}
const analysisEvents=demoEvents();
function periodEvents(){return analysisEvents.filter(e=>e.minute<=lab.minute&&(lab.period==='all'||(lab.period==='first'?e.minute<=45:e.minute>45)));}
function selectedEvents(){return periodEvents().filter(e=>e.side===lab.team&&(lab.player==='all'||e.player===Number(lab.player)));}
function poissonOutcome(home,away){
  const distribution=lambda=>{const p=[Math.exp(-lambda)];for(let k=1;k<=30;k++)p[k]=p[k-1]*lambda/k;return p;};
  const a=distribution(home),b=distribution(away),result=[0,0,0];
  a.forEach((x,i)=>b.forEach((y,j)=>result[i>j?0:i===j?1:2]+=x*y));
  const total=result.reduce((a,b)=>a+b,0);return result.map(x=>100*x/total);
}
function percentageParts(values){const total=values.reduce((a,b)=>a+b,0);const first=Math.round(values[0]/total*1000)/10,second=Math.round(values[1]/total*1000)/10;return [first,second,Math.round((100-first-second)*10)/10];}
function resultBar(values,labels=['Thắng','Hòa','Thua']){const pct=percentageParts(values);return `<div class="result-bar">${pct.map((v,i)=>`<span class="result-part result-${i}" style="flex:${v}" title="${labels[i]} ${v.toFixed(1)}%"></span>`).join('')}</div><div class="result-legend">${pct.map((v,i)=>`<span><i class="result-${i}"></i>${labels[i]} <b>${v.toFixed(1)}%</b></span>`).join('')}</div>`;}
function pitchLines(){return '<g stroke="#d8eee0" stroke-opacity=".65" stroke-width="1" fill="none"><rect x="8" y="8" width="584" height="344"/><path d="M300 8v344M8 90h90v180H8M592 90h-90v180h90M8 140h32v80H8M592 140h-32v80h32"/><circle cx="300" cy="180" r="48"/></g>';}
function fieldChart(){
  const rows=selectedEvents(),touches=rows.filter(e=>e.type==='touch'),shots=rows.filter(e=>e.type==='shot'),bins=Array(120).fill(0);
  touches.forEach(e=>bins[Math.min(9,Math.floor(e.y/10))*12+Math.min(11,Math.floor(e.x/100*12))]++);
  const max=Math.max(1,...bins);
  const cells=bins.map((n,i)=>n?`<rect x="${i%12*50}" y="${Math.floor(i/12)*36}" width="50" height="36" fill="hsl(${58-n/max*50} 95% 57%)" opacity="${.2+.7*n/max}"><title>Vùng ${i+1}: ${n} lần chạm (${(n/Math.max(1,touches.length)*100).toFixed(1)}%)</title></rect>`:'').join('');
  return `<svg class="event-pitch" viewBox="0 0 600 360" role="img" aria-label="${lab.view==='heat'?'Sơ đồ nhiệt từ các lần chạm bóng mô phỏng':'Bản đồ cú sút mô phỏng'}"><rect width="600" height="360" fill="#163e35"/>${lab.view==='heat'?cells:''}${pitchLines()}${lab.view==='shots'?shots.map(e=>`<g><circle cx="${e.x*6}" cy="${e.y*3.6}" r="${5+e.xg*28}" fill="${e.goal?'#f6cb5c':e.onTarget?'#8ee0b0':'#9eaec5'}" stroke="white" stroke-width="1.5"><title>${archiveTeams[e.side].starters[e.player][1]} · ${e.minute}′ · xG ${e.xg.toFixed(2)} · ${e.goal?'Bàn thắng':e.onTarget?'Trúng đích':'Không trúng đích'}</title></circle></g>`).join(''):''}</svg><div class="heatmap-legend"><span>Chuẩn hóa hướng tấn công →</span><span>${lab.view==='heat'?'Ít <i class="legend-gradient"></i> Nhiều':'Vàng: bàn · Xanh: trúng đích · Xám: khác'}</span></div><p class="chart-caption">${lab.view==='heat'?`${touches.length} lần chạm trong vùng thời gian đã chọn. Di chuột vào ô để xem mật độ.`:`${shots.length} cú sút. Kích thước vòng tròn tỉ lệ với xG; danh sách bên dưới có chi tiết.`}</p>`;
}
function xgChart(){
  const shots=periodEvents().filter(e=>e.type==='shot'),totals=[0,1].map(side=>sum(shots.filter(e=>e.side===side),'xg')),max=Math.max(1,...totals)*1.15;
  const path=side=>{let total=0,d='M40 188';shots.filter(e=>e.side===side).forEach(e=>{total+=e.xg;d+=` H${40+e.minute/90*510} V${188-total/max*150}`;});return d+` H${40+lab.minute/90*510}`;};
  return `<div class="chart-key">${archiveTeams.map((t,i)=>`<span style="--series:${t.color}"><i></i>${t.name} <b>${totals[i].toFixed(2)}</b></span>`).join('')}</div><svg class="xg-chart" viewBox="0 0 580 225" role="img" aria-label="xG tích lũy mô phỏng, Hà Nội ${totals[0].toFixed(2)}, CAHN ${totals[1].toFixed(2)}">${[0,.5,1].map(f=>`<path d="M40 ${188-f*150}H550" stroke="#e5e9e7"/><text x="3" y="${192-f*150}">${(f*max).toFixed(1)}</text>`).join('')}${[0,15,30,45,60,75,90].map(m=>`<text x="${40+m/90*510}" y="214" text-anchor="middle">${m}′</text>`).join('')}${archiveTeams.map((t,i)=>`<path d="${path(i)}" fill="none" stroke="${t.color}" stroke-width="3"/>`).join('')}</svg><p class="chart-caption">Tổng xG trong khoảng thời gian đã chọn; hai đội luôn hiển thị để so sánh. Mỗi bậc tăng là một cú sút.</p>`;
}
function territoryChart(){
  const events=periodEvents().filter(e=>e.type==='touch'&&e.x>=66.67),counts=Array.from({length:18},(_,i)=>[0,1].map(side=>events.filter(e=>e.side===side&&Math.floor((e.minute-1)/5)===i).length)),max=Math.max(1,...counts.flat());
  return `<svg class="pressure-chart" viewBox="0 0 580 160" role="img" aria-label="Số lần chạm bóng ở một phần ba sân tấn công, theo từng 5 phút"><path d="M35 72H555" stroke="#afbbb5"/>${counts.map((v,i)=>v.map((n,side)=>`<rect x="${40+i*28}" y="${side===0?72-n/max*54:75}" width="18" height="${n/max*54}" rx="2" fill="${archiveTeams[side].color}"><title>${i*5+1}–${i*5+5}′ · ${archiveTeams[side].name}: ${n} lần chạm</title></rect>`).join('')).join('')}${[0,3,6,9,12,15,18].map(i=>`<text x="${36+i*28}" y="150">${i*5}′</text>`).join('')}</svg><p class="chart-caption">Trên: Hà Nội · Dưới: CAHN. Đếm lần chạm trong ⅓ sân tấn công mỗi 5 phút, không phải chỉ số áp lực chính thức.</p>`;
}
function eventStats(){return archiveTeams[lab.team].starters.map((p,i)=>{const rows=periodEvents().filter(e=>e.side===lab.team&&e.player===i),shots=rows.filter(e=>e.type==='shot');return {i,name:p[1],number:p[0],touches:rows.filter(e=>e.type==='touch').length,shots:shots.length,xg:sum(shots,'xg'),goals:shots.filter(e=>e.goal).length};}).sort((a,b)=>b[lab.statSort]-a[lab.statSort]);}
function labOutput(){
  const selected=selectedEvents(),shots=selected.filter(e=>e.type==='shot'),goals=shots.filter(e=>e.goal).length;
  return `<div class="metrics analytics-metrics">${metric('Chạm bóng',selected.filter(e=>e.type==='touch').length,'Trong bộ lọc sự kiện','pitch')}${metric('Cú sút',shots.length,'Trong bộ lọc sự kiện','chart')}${metric('xG',sum(shots,'xg').toFixed(2),'Tổng chất lượng cơ hội mẫu','chart')}${metric('Bàn − xG',(goals-sum(shots,'xg')).toFixed(2),`${goals} bàn trong kịch bản mẫu`,'cup')}</div><div class="analytics-grid"><section class="panel analytic-card"><div class="analytic-header"><div><h2>Không gian hoạt động</h2><p>${archiveTeams[lab.team].name} · ${lab.player==='all'?'Cả đội':archiveTeams[lab.team].starters[+lab.player][1]}</p></div><div class="segmented">${[['heat','Nhiệt'],['shots','Cú sút']].map(([id,n])=>`<button data-lab-view="${id}" class="${lab.view===id?'active':''}" aria-pressed="${lab.view===id}">${n}</button>`).join('')}</div></div>${fieldChart()}<details><summary>Chi tiết ${shots.length} cú sút trong bộ lọc</summary><div class="shot-list">${shots.map(e=>`<div><b>${e.minute}′</b><span>${archiveTeams[e.side].starters[e.player][1]}</span><span>${e.goal?'⚽ Bàn thắng':e.onTarget?'Trúng đích':'Không trúng đích'}</span><b>${e.xg.toFixed(2)} xG</b></div>`).join('')||'<p>Chưa có cú sút trong khoảng này.</p>'}</div></details></section><div class="analysis-stack"><section class="panel analytic-card"><h2>Chất lượng cơ hội theo thời gian</h2>${xgChart()}</section><section class="panel analytic-card"><h2>Hiện diện ở vùng tấn công</h2>${territoryChart()}</section></div></div><section class="panel section-gap"><div class="panel-header"><div><h2>Thống kê cầu thủ trong trận mẫu</h2><p>Toàn đội trong khoảng thời gian đã chọn · Chọn tên để xem sơ đồ nhiệt</p></div><label>Sắp xếp <select class="select" id="event-sort">${[['touches','Chạm bóng'],['shots','Cú sút'],['xg','xG'],['goals','Bàn thắng']].map(([id,n])=>`<option value="${id}" ${lab.statSort===id?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="table-wrap"><table><thead><tr><th>Số áo</th><th>Cầu thủ</th><th>Chạm bóng</th><th>Sút</th><th>xG</th><th>Bàn</th></tr></thead><tbody>${eventStats().map(r=>`<tr><td>${r.number}</td><td><button class="text-link" data-event-player="${r.i}">${r.name}</button></td><td>${r.touches}</td><td>${r.shots}</td><td>${r.xg.toFixed(2)}</td><td>${r.goals}</td></tr>`).join('')}</tbody></table></div></section>`;
}
function probabilityOutput(){return resultBar(poissonOutcome(...lab.lambda),['Hà Nội thắng','Hòa','CAHN thắng']);}
function analyticsPage(){if(state.league!=='V.League 1')return heading('Phòng phân tích trận đấu','V.League 2')+'<div class="panel empty">Chưa có bộ sự kiện V.League 2. Chọn V.League 1 để trải nghiệm mô hình.</div>';return heading('Đọc trận đấu qua dữ liệu','Hà Nội × Công an Hà Nội · Phòng phân tích tương tác','<span class="sample-tag">Sự kiện mô phỏng · 90 phút</span>')+`<div class="analysis-notice">${icon('info')} Tọa độ, cú sút và xG dưới đây là bộ dữ liệu tạo để thử tính năng, không mô tả trận thực ngày 08/03/2026. ${sourceLink('#lineups','Xem đội hình có nguồn →')}</div><div class="panel lab-controls"><label>Đội phân tích<select id="lab-team">${archiveTeams.map((t,i)=>`<option value="${i}" ${lab.team===i?'selected':''}>${t.name}</option>`).join('')}</select></label><label>Cầu thủ<select id="lab-player"><option value="all">Tất cả cầu thủ</option>${archiveTeams[lab.team].starters.map((p,i)=>`<option value="${i}" ${lab.player===String(i)?'selected':''}>${p[0]} · ${p[1]}</option>`).join('')}</select></label><label>Giai đoạn<select id="lab-period">${[['all','Cả trận'],['first','Hiệp 1'],['second','Hiệp 2']].map(([id,n])=>`<option value="${id}" ${lab.period===id?'selected':''}>${n}</option>`).join('')}</select></label><label class="minute-control">Đến phút <output id="lab-minute-value">${lab.minute}′</output><input type="range" id="lab-minute" aria-label="Giới hạn phút phân tích" min="0" max="90" value="${lab.minute}"></label></div><div id="lab-output">${labOutput()}</div><section class="panel analytic-card section-gap"><div class="analytic-header"><div><h2>Xác suất thắng · hòa · thua</h2><p>Mô hình Poisson trước trận · Kịch bản do bạn điều chỉnh</p></div><span class="sample-tag">Chưa hiệu chỉnh</span></div><div class="probability-grid"><div>${archiveTeams.map((t,i)=>`<label class="lambda-label">Bàn kỳ vọng giả định · ${t.name}<output id="lambda-value-${i}">${lab.lambda[i].toFixed(1)}</output><input id="lambda-${i}" aria-label="Bàn kỳ vọng giả định của ${t.name}" type="range" min="0.1" max="4" step="0.1" value="${lab.lambda[i]}"></label>`).join('')}</div><div id="probability-output">${probabilityOutput()}</div></div><details><summary>Cách tính và giới hạn</summary><p>Mỗi đội có số bàn theo phân phối Poisson độc lập với λ do bạn chọn. Cộng xác suất các tỉ số 0–30 bàn và chuẩn hóa về 100%. Không dùng xG diễn biến để coi như dự báo trước trận; không có lợi thế sân nhà, thẻ đỏ hay hiệu chỉnh giải đấu. Đây không phải xác suất trực tiếp hoặc tỷ lệ của nhà cái.</p></details></section>`;}
function lineupPitch(t){const groups=['TM','HV','TV','TĐ'];return `<div class="named-pitch" aria-label="Bố trí cầu thủ minh họa theo nhóm vị trí">${groups.map((pos,row)=>{const list=t.starters.filter(p=>p[2]===pos);return `<div class="pitch-row pitch-row-${row}">${list.map(p=>`<div><b style="background:${t.color}">${p[0]}</b><span>${p[1]}</span></div>`).join('')}</div>`;}).join('')}</div><p class="chart-caption">Vị trí trên sân được bố trí theo nhóm TM/HV/TV/TĐ của danh sách; không xác nhận sơ đồ chiến thuật hay tọa độ thi đấu.</p>`;}
function lineupsPage(){return heading('Đội hình & hồ sơ trận đấu','Hà Nội – Công an Hà Nội · Vòng 15 · V.League 1 2025/26','<span class="verified-badge">✓ Danh sách VPF</span>')+(state.league!=='V.League 1'?'<div class="panel empty">Chưa có danh sách thi đấu V.League 2 được xác minh.</div>':`<div class="archive-banner"><div><b>08/03/2026 · 19:15 · Hàng Đẫy</b><p>Bản lưu trữ danh sách đăng ký thi đấu · Kiểm tra nguồn: 27/09/2026</p></div>${sourceLink(rosterSource,'Mở danh sách VPF ↗')}</div><div class="analytics-grid">${archiveTeams.map(t=>`<section class="panel analytic-card"><div class="analytic-header"><div><h2>${t.name}</h2><p>HLV trưởng: <strong>${t.coach}</strong></p></div><span class="verified-badge">11 đá chính</span></div>${lineupPitch(t)}<h3>Đá chính · Thành tích trước trận</h3><div class="table-wrap"><table><thead><tr><th>#</th><th>Cầu thủ</th><th>VT</th><th>Trận</th><th>Bàn</th></tr></thead><tbody>${t.starters.map(p=>`<tr><td>${p[0]}</td><td>${p[1]}</td><td>${p[2]}</td><td>${p[3]}</td><td>${p[4]}</td></tr>`).join('')}</tbody></table></div><h3 class="section-gap">Dự bị / SUB <span class="tab-count">${t.subs.length}</span></h3><ul class="subs-list">${t.subs.map(p=>`<li><b>${p[0]}</b><span>${p[1]}</span><small>${p[2]}</small></li>`).join('')}</ul><p class="chart-caption">Có tên trong danh sách dự bị không đồng nghĩa đã vào sân. Chưa có phút thay người được xác minh.</p><h3>Tỉ lệ kết quả trước trận</h3>${resultBar(t.record)}<p class="chart-caption">${t.record.reduce((a,b)=>a+b,0)} trận · ${t.record[0]} thắng · ${t.record[1]} hòa · ${t.record[2]} thua. Thành tích được ghi trên danh sách VPF ngày 08/03/2026, không phải dự báo.</p></section>`).join('')}</div><div class="analysis-notice">${icon('info')} Các số trận và bàn thắng là số liệu trước trận trong tài liệu VPF. Tên cầu thủ được giữ theo tài liệu, không suy ra đội hình hiện tại. <a class="text-link" href="#analytics">Thử biểu đồ với sự kiện mô phỏng →</a></div>`);}
const renewalURL='https://cahnfc.com/tin-tuc/THONG-CAO-BAO-CHI-or-CLB-CONG-AN-HA-NOI-GIA-HAN-HOP-DONG-VOI-04-CAU-THU-CHU-CHOT.769';
const transferRecords=[
  ...['Cyrus Christie','Adam Taggart','Aymeric Faurand-Tournaire'].map(name=>({name,club:'Hà Nội',type:'in',date:'2026-09-04',source:'https://hanoifc.com.vn/video',note:'CLB đăng video chào mừng cầu thủ. Ngày hiển thị là ngày đăng video.'})),
  {name:'Damià Sabater',club:'Công an Hà Nội',type:'in',date:'2026-07-06',source:'https://cahnfc.com/en/tin-tuc/CHINH-THUC-CLB-CONG-AN-HA-NOI-CHIEU-MO-TIEN-VE-DAMIA-SABATER-TU-TAY-BAN-NHA.796',note:'CLB thông báo chiêu mộ ngày 05/07; bài được đăng ngày 06/07/2026.'},
  ...['Đoàn Văn Hậu','Lê Phạm Thành Long','Trần Đình Trọng','Alan Grafite'].map(name=>({name,club:'Công an Hà Nội',type:'renew',date:'2026-04-16',source:renewalURL,note:'Thông cáo gia hạn với 4 cầu thủ chủ chốt của CLB.'}))
];
function filteredTransfers(){return state.league!=='V.League 1'?[]:transferRecords.filter(r=>(lab.transferType==='all'||r.type===lab.transferType)&&(lab.transferClub==='all'||r.club===lab.transferClub)&&norm(r.name+' '+r.club).includes(norm(lab.query)));}
function transferResults(){const rows=filteredTransfers();return `<div class="market-result-count" role="status">${rows.length} bản ghi phù hợp · Thông báo từ CLB</div><div class="transfer-grid">${rows.map(r=>`<article class="panel transfer-card"><div class="analytic-header"><span class="${r.type==='in'?'verified-badge':'renewal-badge'}">${r.type==='in'?'Gia nhập':'Gia hạn'}</span><time datetime="${r.date}">${r.date.split('-').reverse().join('/')}</time></div><div class="transfer-initials">${r.name.split(' ').slice(-2).map(s=>s[0]).join('')}</div><h2>${r.name}</h2><p class="transfer-destination">${r.type==='in'?'Gia nhập':'Tiếp tục tại'} <strong>${r.club}</strong></p><div class="transfer-facts"><div><span>Phí chuyển nhượng</span><b>Chưa xác minh</b></div><div><span>Thời hạn hợp đồng</span><b>Chưa xác minh</b></div></div><p>${r.note}</p>${sourceLink(r.source,'Đọc thông báo của CLB ↗')}</article>`).join('')||'<div class="panel empty">Không có thông báo phù hợp trong dữ liệu đã xác minh. Hãy đổi bộ lọc.</div>'}</div>`;}
function transfersPage(){return heading('Thị trường chuyển nhượng','Theo dõi thông báo gia nhập và gia hạn từ các câu lạc bộ.','<span class="verified-badge">✓ Đối chiếu 27/09/2026</span>')+`<div class="market-hero"><div><span class="eyebrow">TRANSFER CENTRE</span><h2>Ai đến. Ai ở lại.</h2><p>Thông tin có nguồn, ngày công bố rõ ràng.<br>Kho dữ liệu đang mở rộng theo từng thông báo.</p></div><div class="market-number"><b>${state.league==='V.League 1'?8:0}</b><span>bản ghi đã đối chiếu</span></div></div><div class="panel lab-controls"><label>Tìm cầu thủ<input type="search" id="transfer-search" placeholder="Tên cầu thủ hoặc CLB…" value="${esc(lab.query)}"></label><label>Giao dịch<select id="transfer-type">${[['all','Tất cả'],['in','Gia nhập'],['renew','Gia hạn']].map(([id,n])=>`<option value="${id}" ${lab.transferType===id?'selected':''}>${n}</option>`).join('')}</select></label><label>Câu lạc bộ<select id="transfer-club">${['all','Hà Nội','Công an Hà Nội'].map(n=>`<option value="${n}" ${lab.transferClub===n?'selected':''}>${n==='all'?'Tất cả CLB':n}</option>`).join('')}</select></label></div><div id="transfer-results">${transferResults()}</div><p class="data-note">${icon('info')} Ngày trên thẻ là ngày nguồn công bố. Dữ liệu cập nhật thủ công, chưa bao quát toàn bộ thị trường. Phí chưa xác minh không được coi là 0 € hay chuyển nhượng tự do.</p>`;}
pageViews.analytics=analyticsPage;pageViews.lineups=lineupsPage;pageViews.transfers=transfersPage;
nav.splice(2,0,['analytics','Phân tích trận','chart'],['lineups','Đội hình thi đấu','pitch']);nav.splice(6,0,['transfers','Chuyển nhượng','compare']);
const originalV3Matches=matchesPage;
matchesPage=function(){return originalV3Matches()+`<div class="explore-links"><a class="panel" href="#lineups"><b>Đội hình có nguồn VPF →</b><span>Hà Nội – CAHN · 08/03/2026 · 22 đá chính, 18 dự bị, 2 HLV</span></a><a class="panel" href="#analytics"><b>Phòng phân tích trận →</b><span>Sơ đồ nhiệt, bản đồ sút, xG và xác suất trong kịch bản mô phỏng</span></a></div>`;};pageViews.matches=matchesPage;
const originalV3Overview=overview;
overview=function(){return originalV3Overview()+`<div class="explore-links"><a class="panel" href="#analytics"><b>Khám phá biểu đồ trận đấu →</b><span>Lọc cầu thủ, thời gian và vùng hoạt động</span></a><a class="panel" href="#transfers"><b>Thị trường chuyển nhượng →</b><span>Thông báo gia nhập và gia hạn từ CLB</span></a></div>`;};pageViews.overview=overview;
const originalV3Sources=sourcesPage;
sourcesPage=function(){return originalV3Sources().replace('Tỉ số trực tiếp, hồ sơ chi tiết và dữ liệu sự kiện chưa kết nối.', 'Đã bổ sung danh sách thi đấu Hà Nội–CAHN ngày 08/03/2026 và 8 thông báo chuyển nhượng có nguồn. Tỉ số trực tiếp và dữ liệu sự kiện chưa kết nối.')+`<section class="panel analytic-card section-gap"><h2>Nguồn bổ sung · Kiểm tra 27/09/2026</h2><p>Đội hình, cầu thủ dự bị, HLV, thành tích trước trận: ${sourceLink(rosterSource,'VPF · 08/03/2026 ↗')}.</p><p>Thông báo giao dịch: ${sourceLink(renewalURL,'CAHN · Gia hạn ↗')} · ${sourceLink(transferRecords[3].source,'CAHN · Damià Sabater ↗')} · ${sourceLink('https://hanoifc.com.vn/video','Hà Nội FC · Chào mừng cầu thủ ↗')}.</p><p>Sơ đồ nhiệt mới đếm 880 lần chạm mô phỏng thành lưới 12 × 10. Biểu đồ xG tích lũy cộng 25 cú sút mẫu. Đây là dữ liệu thử tính năng độc lập với đội hình lưu trữ; không có dữ liệu Opta hay tracking được kết nối.</p></section>`;};pageViews.sources=sourcesPage;
// Keep the existing detailed profiles; make the richer event dashboard discoverable.
const originalV3ShowMatch=showMatch;
showMatch=function(id,tab='stats'){originalV3ShowMatch(id,tab);const content=$('#detail-content .detail-main');if(content)content.insertAdjacentHTML('beforeend','<div class="explore-links"><a href="#analytics" class="button">Biểu đồ & sơ đồ nhiệt mô phỏng →</a><a href="#lineups" class="button">Đội hình lưu trữ VPF · 08/03/2026 →</a></div>');};
function updateLab(){const out=$('#lab-output');if(out)out.innerHTML=labOutput();}
document.addEventListener('change',e=>{
  const id=e.target.id,v=e.target.value;
  if(id==='lab-team'){lab.team=+v;lab.player='all';render();}
  if(id==='lab-player'){lab.player=v;updateLab();}
  if(id==='lab-period'){lab.period=v;updateLab();}
  if(id==='event-sort'){lab.statSort=v;updateLab();}
  if(id==='transfer-type'||id==='transfer-club'){lab[id==='transfer-type'?'transferType':'transferClub']=v;$('#transfer-results').innerHTML=transferResults();}
});
document.addEventListener('input',e=>{
  if(e.target.id==='lab-minute'){lab.minute=+e.target.value;$('#lab-minute-value').textContent=lab.minute+'′';updateLab();}
  if(/^lambda-[01]$/.test(e.target.id)){const i=+e.target.id.slice(-1);lab.lambda[i]=+e.target.value;$('#lambda-value-'+i).textContent=lab.lambda[i].toFixed(1);$('#probability-output').innerHTML=probabilityOutput();}
  if(e.target.id==='transfer-search'){lab.query=e.target.value;$('#transfer-results').innerHTML=transferResults();}
});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.labView){lab.view=el.dataset.labView;updateLab();}if(el.dataset.eventPlayer!==undefined){lab.player=el.dataset.eventPlayer;lab.view='heat';$('#lab-player').value=lab.player;updateLab();$('#lab-output').scrollIntoView({behavior:'smooth',block:'start'});}});
render();
